  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']

    n = len(nodes)
    if n < 2:
        raise ValueError('Need at least 2 nodes')

    # Build set of edges with canonical ordering (node1 < node2) and mutual reachability
    edges = []
    for a, b, d in distances:
        # canonicalize undirected endpoints
        if a < b:
            u, v = a, b
        else:
            u, v = b, a
        weight = max(core_dist[u], core_dist[v], d)
        edges.append((weight, u, v))

    # Sort by weight, then by node1, then node2
    edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) < n - 1:
        raise ValueError('Graph is disconnected, cannot form MST')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
